root.script:
// Track the output element
var outputBox = Element.new(2)  // The output box

// Counter for events
var eventCount = 0

// Listen for keypress events on the document
document.addEventListener("keypress", Fn.new { |event|
    eventCount = eventCount + 1
    System.print("Keypress event #" + eventCount.toString + ": " + event["key"])

    // Create a new text element showing the key pressed
    var text = document.createText("Key pressed: " + event["key"] + " (event #" + eventCount.toString + ")")
    outputBox.append(text)
})

System.print("Event listener registered!")
